/** Certified process-death cuts in the real authoritative writer; not a host power-loss simulation. */
class LmdbPersistentAdjacencyCertifiedCrashTest {

	private static final String OLD_PREFERENCES = "spoc";
	private static final String NEW_PREFERENCES = "opsc,posc,spoc";
	private static final int BASE_ROWS_PER_PLANE = 2 * LmdbPersistentAdjacency.PAGE_QUADS + 16;
	private static final int EXIT_AT_CUT = 86;
	private static final int WITNESS_MAGIC = 0x41444331;

	@TempDir(cleanup = CleanupMode.ON_SUCCESS)
	Path directory;

	@ParameterizedTest
	@EnumSource(Cut.class)
	@Timeout(90)
	void onlyCompleteNativeAuthoritySurvivesCertifiedProcessDeath(Cut cut) throws Exception {
		Path data = directory.resolve("store");
		Seed seed = seed(data, cut);
		Path witnessFile = directory.resolve("cut.witness");
		Path output = directory.resolve("child.log");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		String mockitoAgent = "-javaagent:"
				+ Path.of(Mockito.class.getProtectionDomain().getCodeSource().getLocation().toURI());
		Process child = new ProcessBuilder(java, "-ea", "-Xmx384m", "-XX:ActiveProcessorCount=2",
				"-XX:-CreateCoredumpOnCrash", "-XX:ErrorFile=" + directory.resolve("hs_err_pid%p.log"),
				"--enable-native-access=ALL-UNNAMED", mockitoAgent, "-cp", System.getProperty("java.class.path"),
				CrashChild.class.getName(), data.toString(), cut.name(), witnessFile.toString())
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			assertTrue(child.waitFor(60, TimeUnit.SECONDS), "the owned child must reach its certified cut: " + output);
			String evidence = Files.readString(output);
			assertEquals(EXIT_AT_CUT, child.exitValue(), evidence);
			assertThat(evidence).contains("CERTIFIED_ADJACENCY_CUT=" + cut.name());
			assertThat(witnessFile).exists();
		} finally {
			reap(child);
		}
		Witness witness = readWitness(witnessFile);
		assertEquals(cut, witness.cut());
		assertThat(witness.writer()).isNotZero();
		assertThat(witness.environment()).isNotZero();
		assertThat(Set.of(witness.pagesDbi(), witness.metadataDbi(), witness.deltasDbi())).hasSize(3);
		assertThat(witness.stagedDeltas()).isEqualTo(cut.sidecar ? 576 : 1152);
		assertThat(witness.deltaPuts()).isGreaterThanOrEqualTo(witness.stagedDeltas());
		assertEquals(witness.revisionBefore(), witness.revisionAtCut(), "halt precedes Java revision publication");
		assertEquals(witness.generationBefore(), witness.generationAtCut(), "halt precedes outer commit bookkeeping");
		assertEquals(cut.committed ? 1 : 0, witness.nativeCommits());
		if (cut == Cut.STAGED_BEFORE_COMPACTION) {
			assertEquals(0, witness.deltaDeletes());
			assertEquals(0, witness.pagePuts());
		} else {
			assertThat(witness.deltaDeletes()).isPositive();
			if (cut == Cut.DELTAS_DELETED_BEFORE_PAGE_PUT) {
				assertEquals(0, witness.pagePuts());
			} else {
				assertEquals(witness.stagedDeltas(), witness.deltaDeletes());
				assertThat(witness.pagePuts()).isPositive();
			}
		}
		assertThat(Files.readAllBytes(data.resolve(StoreProperties.FILE_NAME))).isEqualTo(seed.sidecar());
		assertTrue(witness.sidecarUnchanged());
		assertEquals(cut.sidecar ? NEW_PREFERENCES : OLD_PREFERENCES, witness.preferences());
		Set<Quad> expected = cut.committed ? witness.expected() : seed.model();
		if (!cut.committed) {
			assertEquals(seed.model(), witness.expected());
			assertEquals(seed.authority(), witness.authority(), "the pre-commit recovery oracle is the durable seed");
		} else if (!cut.sidecar) {
			assertEquals(changedFixture(false), expected);
		}
		Map<String, Map<String, String>> firstReopen = null;
		for (int reopen = 0; reopen < 2; reopen++) {
			Map<String, Map<String, String>> current;
			if (cut.sidecar) {
				// Do not hide the stale sidecar by supplying the child's changed preferences again.
				LmdbStore store = new LmdbStore(data.toFile(), config(null));
				store.init();
				try {
					LmdbSailStore backing = store.getBackingStore();
					assertEquals(numeric(backing.valueStore(), changedFixture(true)), expected);
					current = verify(backing.getTripleStore(), expected);
					assertRdfValues(backing.valueStore(), expected, changedFixture(true));
				} finally {
					store.shutDown();
				}
			} else {
				try (TripleStore store = new TripleStore(data.toFile(), config(OLD_PREFERENCES), null)) {
					current = verify(store, expected);
				}
			}
			assertEquals(witness.authority(), current, "recovery must expose byte-exact committed adjacency authority");
			if (firstReopen != null) {
				assertEquals(firstReopen, current, "a second reopen cannot replay or resurrect a different generation");
			}
			firstReopen = current;
		}
	}

	private static Seed seed(Path data, Cut cut) throws Exception {
		Set<Quad> model;
		Map<String, Map<String, String>> committed;
		if (cut.sidecar) {
			LmdbStore store = new LmdbStore(data.toFile(), config(OLD_PREFERENCES));
			store.init();
			try {
				LmdbSailStore backing = store.getBackingStore();
				backing.enableMultiThreading = false;
				for (boolean explicit : new boolean[] { true, false }) {
					try (SailSink sink = (explicit ? backing.getExplicitSailSource() : backing.getInferredSailSource())
							.sink(IsolationLevels.SNAPSHOT)) {
						for (Quad quad : baseFixture()) {
							if (quad.explicit() == explicit) {
								approve(sink, rdf(quad));
							}
						}
						sink.flush();
					}
				}
				model = numeric(backing.valueStore(), baseFixture());
				committed = verify(backing.getTripleStore(), model);
			} finally {
				store.shutDown();
			}
		} else {
			StoreProperties properties = new StoreProperties(data.toFile()).setVersion("7").setInlineLiterals(false);
			model = baseFixture();
			try (TripleStore store = new TripleStore(data.toFile(), properties, config(OLD_PREFERENCES), null)) {
				store.startTransaction();
				for (Quad quad : model) {
					assertTrue(store.storeTriple(quad.subject(), quad.predicate(), quad.object(), quad.context(),
							quad.explicit()));
				}
				LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
				store.commit();
				committed = verify(store, model);
			}
			properties.save();
		}
		return new Seed(model, committed, Files.readAllBytes(data.resolve(StoreProperties.FILE_NAME)));
	}

	private static LmdbStoreConfig config(String preferences) {
		LmdbStoreConfig config = preferences == null ? new LmdbStoreConfig() : new LmdbStoreConfig(preferences);
		return config.setForceSync(true)
				.setInlineLiterals(false)
				.setTripleDBSize(64L << 20)
				.setValueDBSize(64L << 20)
				.setBulkOperationSize(0)
				.setSketchEstimatorEnabled(false)
				.setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setInitialRunImportEnabled(false);
	}

	private static Set<Quad> baseFixture() {
		Set<Quad> result = new LinkedHashSet<>();
		for (boolean explicit : new boolean[] { true, false }) {
			for (int row = 0; row < BASE_ROWS_PER_PLANE; row++) {
				result.add(baseQuad(row, explicit));
			}
		}
		return result;
	}

	private static Quad baseQuad(int row, boolean explicit) {
		return new Quad(explicit ? 10 : 11, 20, (explicit ? 1000 : 20_000) + 2L * row,
				new long[] { 0, 1, 7 }[row % 3], explicit);
	}

	private static Set<Quad> additions(boolean explicitOnly) {
		Set<Quad> result = new LinkedHashSet<>();
		for (boolean explicit : new boolean[] { true, false }) {
			if (!explicit && explicitOnly) {
				continue;
			}
			for (int row = 0; row < 256; row++) {
				result.add(new Quad(explicit ? 12 : 13, 20, (explicit ? 100_000 : 200_000) + row,
						row % 2 == 0 ? 1 : 7, explicit));
			}
		}
		return result;
	}

	private static Set<Quad> removals(boolean explicitOnly) {
		Set<Quad> result = new LinkedHashSet<>();
		for (boolean explicit : new boolean[] { true, false }) {
			if (!explicit && explicitOnly) {
				continue;
			}
			for (int row = 0; row < 32; row++) {
				result.add(baseQuad(row, explicit));
			}
		}
		return result;
	}

	private static Set<Quad> changedFixture(boolean explicitOnly) {
		Set<Quad> result = baseFixture();
		result.removeAll(removals(explicitOnly));
		result.addAll(additions(explicitOnly));
		return result;
	}

	private static Statement rdf(Quad quad) {
		var vf = SimpleValueFactory.getInstance();
		return vf.createStatement(vf.createIRI("urn:certified-crash:subject:" + quad.subject()),
				vf.createIRI("urn:certified-crash:predicate:" + quad.predicate()),
				vf.createIRI("urn:certified-crash:object:" + quad.object()),
				quad.context() == 0 ? null : vf.createIRI("urn:certified-crash:context:" + quad.context()));
	}

	private static void approve(SailSink sink, Statement statement) {
		sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(), statement.getContext());
	}

	private static Set<Quad> numeric(ValueStore values, Set<Quad> fixture) throws IOException {
		Set<Quad> result = new HashSet<>();
		for (Quad quad : fixture) {
			Statement statement = rdf(quad);
			Quad encoded = new Quad(values.getId(statement.getSubject()), values.getId(statement.getPredicate()),
					values.getId(statement.getObject()),
					statement.getContext() == null ? 0 : values.getId(statement.getContext()), quad.explicit());
			assertThat(new long[] { encoded.subject(), encoded.predicate(), encoded.object(), encoded.context() })
					.doesNotContain(-1L);
			assertTrue(result.add(encoded));
		}
		return result;
	}

	private static void assertRdfValues(ValueStore values, Set<Quad> actual, Set<Quad> fixture) throws IOException {
		for (boolean explicit : new boolean[] { true, false }) {
			Set<Statement> expected = fixture.stream()
					.filter(quad -> quad.explicit() == explicit)
					.map(LmdbPersistentAdjacencyCertifiedCrashTest::rdf)
					.collect(Collectors.toSet());
			Set<Statement> decoded = new HashSet<>();
			for (Quad quad : actual) {
				if (quad.explicit() == explicit) {
					decoded.add(SimpleValueFactory.getInstance()
							.createStatement((Resource) values.getValue(quad.subject()),
									(org.eclipse.rdf4j.model.IRI) values.getValue(quad.predicate()),
									values.getValue(quad.object()),
									quad.context() == 0 ? null : (Resource) values.getValue(quad.context())));
				}
			}
			assertEquals(expected, decoded);
		}
	}

	private static Map<String, Map<String, String>> verify(TripleStore store, Set<Quad> expected) throws IOException {
		return store.getTxnManager().doWith((stack, txn) -> {
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn);
			assertSnapshot(adjacency, txn, expected, true);
			return authority(txn, adjacency);
		});
	}

	/** Independent complete metadata oracle, including every value reference occurrence, not a fixed sample of IDs. */
	private static void assertSnapshot(LmdbPersistentAdjacency adjacency, long txn, Set<Quad> expected,
			boolean compacted) throws IOException {
		int main = LmdbUtil.openDatabaseWithTxn(txn, null, 0);
		Set<String> databaseNames = records(txn, main).keySet()
				.stream()
				.map(key -> new String(HexFormat.of().parseHex(key), StandardCharsets.UTF_8))
				.collect(Collectors.toSet());
		assertThat(databaseNames).as("the crash oracle reads actual persistent statement authority")
				.contains(LmdbPersistentAdjacency.PAGES_DATABASE, LmdbPersistentAdjacency.METADATA_DATABASE,
						LmdbPersistentAdjacency.DELTAS_DATABASE)
				.noneMatch(name -> name.matches("([spoc]{4})\\1(?:-inf)?"));
		for (boolean explicit : new boolean[] { true, false }) {
			Set<Quad> plane = expected.stream().filter(quad -> quad.explicit() == explicit).collect(Collectors.toSet());
			for (String order : List.of("psoc", "posc")) {
				Set<Quad> actual = new HashSet<>();
				try (RecordIterator iterator = adjacency.scan(txn, -1, -1, -1, -1, explicit, order)) {
					for (long[] row = iterator.next(); row != null; row = iterator.next()) {
						assertTrue(actual.add(new Quad(row[0], row[1], row[2], row[3], explicit)), "no duplicate quad");
					}
				}
				assertEquals(plane, actual, order + " must expose the whole snapshot-local plane");
			}
		}
		Map<String, Long> counts = new HashMap<>();
		for (Quad quad : expected) {
			int outgoing = quad.explicit() ? 0 : 2;
			increment(counts, key(1, outgoing));
			for (int plane = outgoing; plane <= outgoing + 1; plane++) {
				long row = plane == outgoing ? quad.subject() : quad.object();
				increment(counts, key(2, plane, quad.predicate()));
				increment(counts, key(3, plane, quad.predicate(), row));
				increment(counts, key(4, plane, row, quad.predicate()));
			}
			increment(counts, key(5, outgoing, quad.context()));
			increment(counts, key(6, null, quad.context()));
			for (long id : new long[] { quad.subject(), quad.predicate(), quad.object() }) {
				increment(counts, key(7, null, id));
			}
			if (quad.context() != 0) {
				increment(counts, key(7, null, quad.context()));
			}
		}
		Map<String, String> metadata = new TreeMap<>();
		metadata.put("00", "00000001");
		counts.forEach((key, count) -> metadata.put(key,
				HexFormat.of().formatHex(ByteBuffer.allocate(8).putLong(count).array())));
		Map<String, String> actualMetadata = records(txn, adjacency.metadataDbi());
		if (!compacted) {
			actualMetadata.keySet().removeIf(key -> Integer.parseInt(key.substring(0, 2), 16) > 7);
		} else {
			assertThat(records(txn, adjacency.deltasDbi())).isEmpty();
		}
		assertEquals(metadata, actualMetadata, "all plane, row, predicate, context and reference counts must be exact");
	}

	private static void increment(Map<String, Long> counts, String key) {
		counts.merge(key, 1L, Long::sum);
	}

	private static String key(int type, Integer plane, long... ids) {
		ByteBuffer bytes = ByteBuffer.allocate(1 + (plane == null ? 0 : 1) + Long.BYTES * ids.length);
		bytes.put((byte) type);
		if (plane != null) {
			bytes.put(plane.byteValue());
		}
		for (long id : ids) {
			bytes.putLong(id);
		}
		return HexFormat.of().formatHex(bytes.array());
	}

	public static final class CrashChild {
		public static void main(String[] arguments) throws Exception {
			Path data = Path.of(arguments[0]);
			Cut cut = Cut.valueOf(arguments[1]);
			Path witness = Path.of(arguments[2]);
			StoreProperties properties = new StoreProperties(data.toFile());
			assertTrue(properties.load());
			byte[] oldSidecar = Files.readAllBytes(data.resolve(StoreProperties.FILE_NAME));
			if (cut.sidecar) {
				LegacyStoreDiscovery.discover(data.toFile(), properties);
				try (LmdbSailStore backing = new LmdbSailStore(data.toFile(), properties, config(NEW_PREFERENCES),
						false, ValueStore::new, CrashTripleStore::new)) {
					backing.enableMultiThreading = false;
					CrashTripleStore store = (CrashTripleStore) backing.getTripleStore();
					Set<Quad> original = numeric(backing.valueStore(), baseFixture());
					try (Observation observation = new Observation(store, cut, data, witness, properties, oldSidecar,
							original, () -> numeric(backing.valueStore(), changedFixture(true)))) {
						store.armed = observation; // Constructor/setup commits must never satisfy a crash cut.
						try (SailSink sink = backing.getExplicitSailSource().sink(IsolationLevels.SNAPSHOT)) {
							for (Quad quad : removals(true)) {
								sink.deprecate(rdf(quad));
							}
							for (Quad quad : additions(true)) {
								approve(sink, rdf(quad));
							}
							observation.staged(null);
							sink.flush();
						}
					}
				}
			} else {
				try (CrashTripleStore store = new CrashTripleStore(data.toFile(), properties,
						config(OLD_PREFERENCES), null);
						Observation observation = new Observation(store, cut, data, witness, properties, oldSidecar,
								baseFixture(), () -> changedFixture(false))) {
					store.armed = observation;
					store.startTransaction();
					List<Quad> removed = new ArrayList<>();
					for (Quad quad : removals(false)) {
						store.removeTriplesByContext(quad.subject(), quad.predicate(), quad.object(), quad.context(),
								quad.explicit(), row -> removed.add(quad));
					}
					assertEquals(removals(false), new HashSet<>(removed));
					assertEquals(removals(false).size(), removed.size());
					for (Quad quad : additions(false)) {
						assertTrue(store.storeTriple(quad.subject(), quad.predicate(), quad.object(), quad.context(),
								quad.explicit()));
					}
					observation.staged(changedFixture(false));
					store.commit();
				}
			}
			throw new AssertionError("The actual writer never reached its certified crash cut " + cut);
		}
	}

	private static final class CrashTripleStore extends TripleStore {
		Observation armed;

		CrashTripleStore(File directory, StoreProperties properties, LmdbStoreConfig config, ValueStore values)
				throws IOException {
			super(directory, properties, config, values);
		}

		@Override
		int commitWriteTransaction(long transaction) {
			Observation current = armed;
			if (current != null) {
				current.beforeNativeCommit(transaction);
			}
			int result = super.commitWriteTransaction(transaction);
			if (current != null) {
				assertEquals(MDB_SUCCESS, result);
				current.afterNativeCommit();
			}
			return result;
		}
	}

	@FunctionalInterface
	private interface ModelSupplier {
		Set<Quad> get() throws IOException;
	}

	private static final class Observation implements AutoCloseable {
		final CrashTripleStore store;
		final Cut cut;
		final Path data;
		final Path witness;
		final StoreProperties properties;
		final byte[] oldSidecar;
		final Set<Quad> original;
		final Map<String, Map<String, String>> originalAuthority;
		final ModelSupplier intended;
		final LmdbPersistentAdjacency adjacency;
		final long revisionBefore;
		final long generationBefore;
		final Thread owner = Thread.currentThread();
		final Map<Long, Integer> cursors = new HashMap<>();
		final MockedStatic<LMDB> nativeCalls;
		long writer;
		int deltaPuts;
		int deltaDeletes;
		int pagePuts;
		int nativeCommits;
		int stagedDeltas;
		Set<Quad> committedModel;
		Map<String, Map<String, String>> committedAuthority;

		Observation(CrashTripleStore store, Cut cut, Path data, Path witness, StoreProperties properties,
				byte[] oldSidecar, Set<Quad> original, ModelSupplier intended) throws IOException {
			this.store = store;
			this.cut = cut;
			this.data = data;
			this.witness = witness;
			this.properties = properties;
			this.oldSidecar = oldSidecar;
			this.original = original;
			this.intended = intended;
			originalAuthority = verify(store, original);
			adjacency = store.getTxnManager().doWith((stack, txn) -> LmdbPersistentAdjacency.openExisting(txn));
			revisionBefore = store.getDataRevision();
			generationBefore = store.getNativeCommitGeneration();
			nativeCalls = mockStatic(LMDB.class, call -> {
				String method = call.getMethod().getName();
				if (method.equals("mdb_txn_begin") && (long) call.getArgument(0) == store.env
						&& ((int) call.getArgument(2) & LMDB.MDB_RDONLY) == 0) {
					Object result = call.callRealMethod();
					if ((int) result == MDB_SUCCESS) {
						assertEquals(0L, writer, "one actual native writer owns this certified attempt");
						assertEquals(owner, Thread.currentThread());
						writer = ((PointerBuffer) call.getArgument(3)).get(0);
					}
					return result;
				}
				if (method.equals("mdb_cursor_open") && (long) call.getArgument(0) == writer && writer != 0) {
					Object result = call.callRealMethod();
					if ((int) result == MDB_SUCCESS) {
						assertThat(cursors.put(((PointerBuffer) call.getArgument(2)).get(0), call.getArgument(1)))
								.isNull();
					}
					return result;
				}
				if (method.equals("mdb_cursor_close")) {
					cursors.remove(call.getArgument(0));
					return call.callRealMethod();
				}
				boolean keyDelete = method.equals("mdb_del") && (long) call.getArgument(0) == writer
						&& (int) call.getArgument(1) == adjacency.deltasDbi();
				boolean cursorDelete = method.equals("mdb_cursor_del")
						&& Integer.valueOf(adjacency.deltasDbi()).equals(cursors.get(call.getArgument(0)));
				if (keyDelete || cursorDelete) {
					Object result = call.callRealMethod();
					if ((int) result == MDB_SUCCESS) {
						deltaDeletes++;
					}
					return result;
				}
				if (method.equals("mdb_put") && (long) call.getArgument(0) == writer && writer != 0) {
					int dbi = call.getArgument(1);
					if (dbi == adjacency.pagesDbi() && cut == Cut.DELTAS_DELETED_BEFORE_PAGE_PUT) {
						assertTrue(deltaDeletes > 0 && pagePuts == 0);
						boolean inCompaction = StackWalker.getInstance()
								.walk(frames -> frames.anyMatch(frame -> frame.getClassName()
										.equals(LmdbPersistentAdjacency.class.getName())
										&& frame.getMethodName().equals("compactPartition")));
						assertTrue(inCompaction);
						certifyAndHalt();
					}
					Object result = call.callRealMethod();
					if ((int) result == MDB_SUCCESS) {
						if (dbi == adjacency.deltasDbi()) {
							deltaPuts++;
						} else if (dbi == adjacency.pagesDbi()) {
							pagePuts++;
						}
					}
					return result;
				}
				if (method.equals("mdb_txn_commit") && (long) call.getArgument(0) == writer && writer != 0) {
					assertThat(cursors).isEmpty();
					Object result = call.callRealMethod();
					if ((int) result == MDB_SUCCESS) {
						nativeCommits++;
					}
					return result;
				}
				return call.callRealMethod();
			});
		}

		void staged(Set<Quad> expected) throws IOException {
			assertEquals(owner, Thread.currentThread());
			assertTrue(writer != 0 && store.writeTxn == writer);
			assertEquals(store.env, LMDB.mdb_txn_env(writer));
			stagedDeltas = records(writer, adjacency.deltasDbi()).size();
			assertEquals(cut.sidecar ? 576 : 1152, stagedDeltas);
			assertThat(deltaPuts).isGreaterThanOrEqualTo(stagedDeltas);
			assertEquals(0, deltaDeletes);
			assertEquals(0, pagePuts);
			if (expected != null) {
				assertSnapshot(adjacency, writer, expected, false);
			}
			if (cut == Cut.STAGED_BEFORE_COMPACTION) {
				certifyAndHalt();
			}
		}

		void beforeNativeCommit(long transaction) {
			try {
				assertEquals(owner, Thread.currentThread());
				assertEquals(writer, transaction);
				assertTrue(stagedDeltas > 0);
				assertEquals(store.env, LMDB.mdb_txn_env(transaction));
				assertThat(cursors).isEmpty();
				assertEquals(0L, store.writeTxn, "the outer owner passed its exact native handle to commit");
				assertEquals(stagedDeltas, deltaDeletes, "every staged delta was absorbed before native commit");
				assertThat(pagePuts).isPositive();
				committedModel = intended.get();
				assertSnapshot(adjacency, transaction, committedModel, true);
				committedAuthority = authority(transaction, adjacency);
				assertThat(cursors).isEmpty();
				if (cut == Cut.COMPACTED_BEFORE_NATIVE_COMMIT) {
					certifyAndHalt();
				}
			} catch (IOException failure) {
				throw new AssertionError("Unable to certify the real pre-commit authority", failure);
			}
		}

		void afterNativeCommit() {
			assertEquals(1, nativeCommits, "the observer must see actual native MDB_SUCCESS, not just Java intent");
			assertTrue(cut.committed);
			certifyAndHalt();
		}

		private void certifyAndHalt() {
			try {
				assertEquals(owner, Thread.currentThread());
				assertEquals(revisionBefore, store.getDataRevision());
				assertEquals(generationBefore, store.getNativeCommitGeneration());
				boolean unchanged = Arrays.equals(oldSidecar,
						Files.readAllBytes(data.resolve(StoreProperties.FILE_NAME)));
				assertTrue(unchanged, "direct backing construction must not save the changed sidecar preferences");
				assertEquals(cut.sidecar ? NEW_PREFERENCES : OLD_PREFERENCES, properties.getTripleIndexes());
				Witness result = new Witness(cut, writer, store.env, adjacency.pagesDbi(), adjacency.metadataDbi(),
						adjacency.deltasDbi(), stagedDeltas, deltaPuts, deltaDeletes, pagePuts, nativeCommits,
						revisionBefore, store.getDataRevision(), generationBefore, store.getNativeCommitGeneration(),
						unchanged, properties.getTripleIndexes(), cut.committed ? committedModel : original,
						cut.committed ? committedAuthority : originalAuthority);
				writeWitness(witness, result);
				System.out.println("CERTIFIED_ADJACENCY_CUT=" + cut.name());
				System.out.flush();
				Runtime.getRuntime().halt(EXIT_AT_CUT);
				throw new AssertionError("Runtime.halt returned");
			} catch (IOException failure) {
				throw new AssertionError("The child must persist its exact native-progress witness before halting",
						failure);
			}
		}

		@Override
		public void close() {
			nativeCalls.close();
		}
	}

	private enum Cut {
		STAGED_BEFORE_COMPACTION(false, false),
		DELTAS_DELETED_BEFORE_PAGE_PUT(false, false),
		COMPACTED_BEFORE_NATIVE_COMMIT(false, false),
		NATIVE_SUCCESS_BEFORE_PUBLICATION(true, false),
		NATIVE_SUCCESS_BEFORE_SIDECAR_SAVE(true, true);

		final boolean committed;
		final boolean sidecar;

		Cut(boolean committed, boolean sidecar) {
			this.committed = committed;
			this.sidecar = sidecar;
		}
	}

	private record Seed(Set<Quad> model, Map<String, Map<String, String>> authority, byte[] sidecar) {
	}

	private record Witness(Cut cut, long writer, long environment, int pagesDbi, int metadataDbi, int deltasDbi,
			int stagedDeltas, int deltaPuts, int deltaDeletes, int pagePuts, int nativeCommits,
			long revisionBefore, long revisionAtCut, long generationBefore, long generationAtCut,
			boolean sidecarUnchanged, String preferences, Set<Quad> expected,
			Map<String, Map<String, String>> authority) {
	}

	private static void writeWitness(Path path, Witness witness) throws IOException {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream out = new DataOutputStream(bytes)) {
			out.writeInt(WITNESS_MAGIC);
			out.writeUTF(witness.cut().name());
			out.writeLong(witness.writer());
			out.writeLong(witness.environment());
			for (int value : new int[] { witness.pagesDbi(), witness.metadataDbi(), witness.deltasDbi(),
					witness.stagedDeltas(), witness.deltaPuts(), witness.deltaDeletes(), witness.pagePuts(),
					witness.nativeCommits() }) {
				out.writeInt(value);
			}
			for (long value : new long[] { witness.revisionBefore(), witness.revisionAtCut(),
					witness.generationBefore(), witness.generationAtCut() }) {
				out.writeLong(value);
			}
			out.writeBoolean(witness.sidecarUnchanged());
			out.writeUTF(witness.preferences());
			out.writeInt(witness.expected().size());
			for (Quad quad : witness.expected()) {
				out.writeLong(quad.subject());
				out.writeLong(quad.predicate());
				out.writeLong(quad.object());
				out.writeLong(quad.context());
				out.writeBoolean(quad.explicit());
			}
			for (String database : List.of("pages", "metadata", "deltas")) {
				Map<String, String> records = witness.authority().get(database);
				out.writeInt(records.size());
				for (var record : records.entrySet()) {
					writeString(out, record.getKey());
					writeString(out, record.getValue());
				}
			}
		}
		try (FileChannel file = FileChannel.open(path, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
			ByteBuffer buffer = ByteBuffer.wrap(bytes.toByteArray());
			while (buffer.hasRemaining()) {
				file.write(buffer);
			}
			file.force(true);
		}
		try (FileChannel parent = FileChannel.open(path.getParent(), StandardOpenOption.READ)) {
			parent.force(true);
		}
	}

	private static Witness readWitness(Path path) throws IOException {
		try (DataInputStream in = new DataInputStream(new ByteArrayInputStream(Files.readAllBytes(path)))) {
			assertEquals(WITNESS_MAGIC, in.readInt());
			Cut cut = Cut.valueOf(in.readUTF());
			long writer = in.readLong();
			long environment = in.readLong();
			int[] counts = new int[8];
			for (int i = 0; i < counts.length; i++) {
				counts[i] = in.readInt();
			}
			long[] revisions = new long[4];
			for (int i = 0; i < revisions.length; i++) {
				revisions[i] = in.readLong();
			}
			boolean sidecar = in.readBoolean();
			String preferences = in.readUTF();
			Set<Quad> model = new HashSet<>();
			int rows = boundedSize(in.readInt());
			for (int i = 0; i < rows; i++) {
				assertTrue(model.add(new Quad(in.readLong(), in.readLong(), in.readLong(), in.readLong(),
						in.readBoolean())));
			}
			Map<String, Map<String, String>> authority = new TreeMap<>();
			for (String database : List.of("pages", "metadata", "deltas")) {
				Map<String, String> records = new TreeMap<>();
				int entries = boundedSize(in.readInt());
				for (int i = 0; i < entries; i++) {
					assertThat(records.put(readString(in), readString(in))).isNull();
				}
				authority.put(database, records);
			}
			assertEquals(-1, in.read(), "the witness must be a complete single certified record");
			return new Witness(cut, writer, environment, counts[0], counts[1], counts[2], counts[3], counts[4],
					counts[5], counts[6], counts[7], revisions[0], revisions[1], revisions[2], revisions[3],
					sidecar, preferences, model, authority);
		}
	}

	private static void writeString(DataOutputStream out, String value) throws IOException {
		byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
		out.writeInt(bytes.length);
		out.write(bytes);
	}

	private static String readString(DataInputStream in) throws IOException {
		byte[] bytes = new byte[boundedSize(in.readInt())];
		in.readFully(bytes);
		return new String(bytes, StandardCharsets.UTF_8);
	}

	private static int boundedSize(int size) {
		assertTrue(size >= 0 && size <= 1_000_000, "bounded complete crash witness");
		return size;
	}

	private static void reap(Process child) throws InterruptedException {
		boolean interrupted = Thread.interrupted();
		try {
			if (child.isAlive()) {
				child.destroyForcibly();
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
				while (child.isAlive() && System.nanoTime() < deadline) {
					try {
						child.waitFor(Math.max(1L, deadline - System.nanoTime()), TimeUnit.NANOSECONDS);
					} catch (InterruptedException interruption) {
						interrupted = true;
					}
				}
				assertThat(child.isAlive()).as("reap the owned native child even after a failed certificate").isFalse();
			}
		} finally {
			if (interrupted) {
				Thread.currentThread().interrupt();
			}
		}
	}
}
